// Special Values (Standard C/C++)
double inf = INFINITY;
double nan = NAN;

// Classification and Properties (<math.h>)
int is_nan = isnan(nan);         // Check if NaN
int is_inf = isinf(inf);         // Check if Infinity
int is_normal = isnormal(1.0);   // Check for normal number

// Accessing Rounding Modes (<fenv.h> required)
// FE_TONEAREST, FE_DOWNWARD, FE_UPWARD, FE_TOWARDZERO
int current_mode = fegetround();
fesetround(FE_DOWNWARD);

// Clearing/Testing Exception Flags (<fenv.h>)
feclearexcept(FE_ALL_EXCEPT);
